"""Embedded relational store: catalog, MVCC rows, indexes, transactions, recovery.

Durability model
----------------
Every commit rewrites a complete, compacted image of the database into the page
file through the WAL: chunk pages for the audit log start at page 1, chunk
pages for the state follow, then one B+ tree page set per index (see
``kvse.btree``), and page 0 is the meta record written last.  The WAL commit
marker therefore makes the whole commit atomic — index pages and table pages
share one commit boundary — and ``reopen`` (or a fresh :class:`Engine` on the
same directory) replays committed WAL records and reproduces exactly the
committed state.  Images written before paged indexes existed carry no index
references in their state record; they open unchanged and their indexes are
rebuilt from the row state in memory, so old ``data.pages``/``wal.log`` files
need no migration.

Concurrency model
-----------------
A single process, single writer engine guarded by one reentrant lock.  Readers
use MVCC snapshot isolation: a transaction reads the newest version that was
committed at or before the horizon it started with, so later commits stay
invisible to it.  Writes are optimistic: touching a row that was written after
the reader's snapshot raises :class:`ConflictError`.

A transaction may also opt into ``serializable`` isolation.  It reads the same
snapshot, but every read additionally records a predicate (a primary key, an
index range, a ``where`` conjunction or a whole table).  At commit time the
engine replays the writes of every transaction that committed after the reader
started — regardless of that writer's isolation level or start order — and
raises :class:`ConflictError` when any written row, before or after the write,
matches a recorded predicate.  A conflicting serializable transaction is
rolled back completely and cannot be used any more.

Savepoints
----------
A transaction may mark named savepoints and later roll back to one of them,
undoing only the writes made after that point while staying alive.  A
savepoint is a bookmark into the transaction's undo and op logs, so rolling
back replays the same undo callbacks a full rollback would, just fewer of
them; read predicates recorded by a serializable transaction deliberately
survive a partial rollback.  Savepoints are purely in-memory: they never
touch the WAL, the lsn or the audit log, and nothing about them survives
commit, rollback, restart or restore.

Foreign keys
------------
A column may carry a ``references`` object ``{"table": T, "column": C}``
naming another table's primary key; the definition is validated when the
table is created and persisted with the catalog.  A null foreign key value
never looks anything up; a non-null value must resolve to a parent row
visible in the transaction's own snapshot (which includes its earlier
writes), and a parent row cannot be deleted while a visible child row still
references it.  Because a concurrent commit can invalidate either check
after it ran, both are repeated at commit time against the newest committed
state; a violation raises :class:`ConstraintError` and rolls the whole
transaction back — no rows, index entries, WAL pages, commit marker, lsn
movement or audit record survive.  Loaded state (reopen, recovery, restore,
replica sync) is validated the same way and rejected with
:class:`StorageError` when a definition or a dangling row does not check
out.
"""

from __future__ import annotations

from __future__ import annotations

import json
import os
import shutil
import tempfile
import threading
import time

from . import btree, query
from .pager import PAGE_SIZE, Pager, StorageError, commit_lsns, read_wal

TYPES = ("int", "text", "bool")
META_PAGE = 0
AUDIT_PAGE = 1
STATE_FORMAT = "kvse-state-1"
DB_FORMAT = "kvse-db-1"
BACKUP_FORMAT = "kvse-backup-1"


class ConflictError(StorageError):
    """Write-write conflict between concurrent snapshot transactions."""


class ConstraintError(StorageError):
    """Primary key, unique, nullability or type constraint violated."""


def _check_savepoint_name(name):
    """A savepoint name is a case-sensitive, non-blank string."""
    if not isinstance(name, str) or not name.strip():
        raise StorageError("savepoint name must be a non-empty, non-blank string")


class Engine:
    """A small relational store persisted in one directory."""

    def __init__(self, root, now_ms=None, page_size=PAGE_SIZE):
        self.root = os.path.abspath(root)
        self.page_size = int(page_size)
        self._now_ms = now_ms
        self._lock = threading.RLock()
        self.pager = Pager(self.root, self.page_size)
        self._reset()
        self._load()

    # ------------------------------------------------------------------ basics
    def _now(self):
        source = self._now_ms
        if source is None:
            return int(time.time() * 1000)
        return int(source() if callable(source) else source)

    def _reset(self):
        self.tables = {}
        self._indexes = {}
        self._audit = []
        self._committed = set()
        self._open = set()
        self._horizon = 0
        self._base_horizon = 0
        self._next_txid = 1
        self._commit_counter = 0
        self._commit_seq = {}
        self.lsn = 0

    def _is_committed(self, txid):
        return txid in self._committed or txid <= self._base_horizon

    def _table(self, name):
        table = self.tables.get(name)
        if table is None:
            raise StorageError("unknown table %s" % name)
        return table

    def has_table(self, name):
        return name in self.tables

    def list_tables(self):
        with self._lock:
            return sorted(self.tables)

    def table_info(self, name):
        with self._lock:
            table = self._table(name)
            return {
                "name": name,
                "columns": [self._column_info(col) for col in table["columns"]],
                "primary_key": table["primary_key"],
                "indexes": dict(table["indexes"]),
                "rows": len(table["rows"]),
            }

    @staticmethod
    def _column_info(column):
        info = dict(column)
        if info.get("references") is not None:
            info["references"] = dict(info["references"])
        return info

    def _reader(self):
        """Pseudo transaction used for engine level reads (txid 0 writes nothing)."""
        return Transaction(self, 0, self._horizon)

    def _coerce_pk(self, table, pk):
        column = [c for c in table["columns"] if c["name"] == table["primary_key"]][0]
        if isinstance(pk, str):
            if column["type"] == "int":
                try:
                    return int(pk)
                except ValueError:
                    raise StorageError("primary key %r is not an int" % pk)
            if column["type"] == "bool":
                if pk.lower() in ("true", "1"):
                    return True
                if pk.lower() in ("false", "0"):
                    return False
                raise StorageError("primary key %r is not a bool" % pk)
        return pk

    # ------------------------------------------------------------------- MVCC
    def _visible(self, versions, txid, horizon):
        """Newest version of a row visible to ``txid`` at ``horizon``."""
        best = None
        for version in versions:
            created = version["created"]
            deleted = version["deleted"]
            if created != txid and not (self._is_committed(created) and created <= horizon):
                continue
            if deleted is None or deleted == txid:
                best = version
            elif not (self._is_committed(deleted) and deleted <= horizon):
                best = version
        return best

    def _conflicting_writes(self, versions, tx):
        """First version written by another transaction after ``tx`` started."""
        for version in versions:
            for marker in (version["created"], version["deleted"]):
                if marker is None or marker == tx.txid:
                    continue
                if marker > tx.snapshot or not self._is_committed(marker):
                    return version
        return None

    # ------------------------------------------------------------- read paths
    def _record_read(self, tx, entry):
        """Remember a read predicate of a serializable transaction.

        Entries are ``("pk", table, pk)``, ``("range", table, column, low,
        high)`` or ``("where", table, conds)`` with an empty ``conds`` meaning
        the whole table.  Only successful reads are recorded, and only when
        the caller is not suppressing recording (see ``Transaction.query``).
        """
        if tx.isolation == "serializable" and not tx._suppress:
            tx._reads.append(entry)

    def _scan(self, tx, table):
        table_obj = self._table(table)
        rows = []
        for pk in sorted(table_obj["rows"], key=query.sort_key):
            version = self._visible(table_obj["rows"][pk], tx.txid, tx.snapshot)
            if version is not None:
                rows.append(dict(version["values"]))
        self._record_read(tx, ("where", table, ()))
        return rows

    def _get(self, tx, table, pk):
        table_obj = self._table(table)
        pk = self._coerce_pk(table_obj, pk)
        versions = table_obj["rows"].get(pk)
        version = self._visible(versions, tx.txid, tx.snapshot) if versions else None
        self._record_read(tx, ("pk", table, pk))
        return dict(version["values"]) if version is not None else None

    def _index_lookup(self, tx, table, column, low, high):
        """Rows whose current version falls inside [low, high], in index order.

        Stale entries left behind by superseded versions are filtered out by
        checking the value of the version this transaction can actually see.
        """
        table_obj = self._table(table)
        if column not in table_obj["indexes"]:
            raise StorageError("no index on %s.%s" % (table, column))
        tree = self._indexes.get((table, column))
        rows = []
        seen = set()
        for value, pk in (tree.iter_range(low, high) if tree is not None else ()):
            if pk in seen:
                continue
            versions = table_obj["rows"].get(pk)
            version = self._visible(versions, tx.txid, tx.snapshot) if versions else None
            if version is None:
                continue
            current = version["values"].get(column)
            if current is None or current != value:
                continue  # stale entry of a superseded version
            if (low is not None and current < low) or (high is not None and current > high):
                continue
            seen.add(pk)
            rows.append(dict(version["values"]))
        self._record_read(tx, ("range", table, column, low, high))
        return rows

    # -------------------------------------------------- serializable checking
    def _predicate_matches(self, entry, values):
        """True when a written row image falls inside a protected read range."""
        if entry[0] == "where":
            return all(query.compare(op, values.get(col), val) for col, op, val in entry[2])
        _, _, column, low, high = entry
        value = values.get(column)
        if value is None:
            return False  # null values are never part of an index range
        try:
            if low is not None and value < low:
                return False
            if high is not None and value > high:
                return False
        except TypeError:
            return False
        return True

    def _check_read_conflicts(self, tx):
        """Validate a serializable transaction against newer committed writes.

        Every version written by a transaction that committed after ``tx``
        started — whatever its isolation level or start order — is checked
        against the predicates ``tx`` recorded while reading.  A write to a
        protected primary key, or a written row whose image before or after
        the write matches a protected predicate, is a read-write conflict.
        """
        by_table = {}
        for entry in tx._reads:
            by_table.setdefault(entry[1], []).append(entry)
        for table, entries in by_table.items():
            table_obj = self.tables.get(table)
            if table_obj is None:
                continue
            protected_pks = {entry[2] for entry in entries if entry[0] == "pk"}
            matchers = [entry for entry in entries if entry[0] != "pk"]
            for pk, versions in table_obj["rows"].items():
                for version in versions:
                    newer = False
                    for marker in (version["created"], version["deleted"]):
                        if marker is None or marker == tx.txid:
                            continue
                        if self._commit_seq.get(marker, 0) > tx._commit_horizon:
                            newer = True
                            break
                    if not newer:
                        continue
                    if pk in protected_pks:
                        raise ConflictError(
                            "key %r of table %s was written by a transaction "
                            "that committed after transaction %d started" % (pk, table, tx.txid)
                        )
                    if any(self._predicate_matches(m, version["values"]) for m in matchers):
                        raise ConflictError(
                            "a transaction that committed after transaction %d started "
                            "wrote rows matching its reads on table %s" % (tx.txid, table)
                        )

    # ------------------------------------------------------------ write paths
    def _read_json(self, page_id):
        payload = self.pager.read_page(page_id).rstrip(b"\x00")
        if not payload:
            raise StorageError("page %d is empty" % page_id)
        return json.loads(payload.decode("utf-8"))

    def _read_pages(self, first_page, count, length):
        chunks = [self.pager.read_page(first_page + i) for i in range(int(count))]
        return b"".join(chunks)[: int(length)]

    def _load(self):
        if self.pager.page_count() == 0:
            return
        meta = self._read_json(META_PAGE)
        if not isinstance(meta, dict) or meta.get("format") != STATE_FORMAT:
            raise StorageError("page 0 does not hold a %s meta record" % STATE_FORMAT)
        self.lsn = int(meta.get("lsn", 0))
        self._horizon = int(meta.get("horizon", 0))
        self._base_horizon = self._horizon
        self._next_txid = max(int(meta.get("next_txid", 1)), self._horizon + 1)
        blob = self._read_pages(meta["state_page"], meta["state_pages"], meta["state_len"])
        state = json.loads(blob.decode("utf-8"))
        if state.get("format") != DB_FORMAT:
            raise StorageError("state blob has an unknown format")
        for name, info in state.get("tables", {}).items():
            table = {
                "name": name,
                "columns": info["columns"],
                "primary_key": info["primary_key"],
                "indexes": {col: "%s_%s_idx" % (name, col) for col in info.get("indexes", [])},
                "rows": {},
            }
            for pk, values in info["rows"]:
                table["rows"][pk] = [{"created": self._horizon, "deleted": None, "values": values}]
            self.tables[name] = table
            self._rebuild_indexes(table)
        index_refs = state.get("index_refs")
        if index_refs is not None:
            # A current image carries paged B+ tree indexes; they must load
            # cleanly and match the committed row state, otherwise the image
            # is refused instead of silently serving wrong index results.
            # Older images have no index pages and keep the in-memory indexes
            # rebuilt above, which yields the same query results.
            self._check_index_pages(index_refs)
        audit_blob = self._read_pages(meta["audit_page"], meta["audit_pages"], meta["audit_len"])
        self._audit = json.loads(audit_blob.decode("utf-8")) if audit_blob else []
        self._validate_foreign_keys()

    def _validate_foreign_keys(self):
        """Reject loaded state whose foreign keys do not hold.

        Every ``references`` entry must name an existing table's primary key
        of the same type, and every non-null foreign key value in a visible
        row must resolve to a visible parent row.  Anything else means the
        state on disk is not one this engine could have committed, so it is
        refused with :class:`StorageError`.
        """
        for name, table in self.tables.items():
            for column in table["columns"]:
                ref = column.get("references")
                if ref is None:
                    continue
                if not isinstance(ref, dict) or set(ref) != {"table", "column"}:
                    raise StorageError(
                        "table %s column %s has a malformed references entry"
                        % (name, column["name"])
                    )
                parent = self.tables.get(ref["table"])
                if parent is None:
                    raise StorageError(
                        "table %s column %s references unknown table %s"
                        % (name, column["name"], ref["table"])
                    )
                if ref["column"] != parent["primary_key"]:
                    raise StorageError(
                        "table %s column %s references %s.%s, which is not the primary key"
                        % (name, column["name"], ref["table"], ref["column"])
                    )
                pk_column = [c for c in parent["columns"] if c["name"] == parent["primary_key"]][0]
                if pk_column["type"] != column["type"]:
                    raise StorageError(
                        "table %s column %s has type %s but references %s.%s of type %s"
                        % (name, column["name"], column["type"],
                           ref["table"], ref["column"], pk_column["type"])
                    )
        for name, table in self.tables.items():
            fk_columns = [c for c in table["columns"] if c.get("references") is not None]
            if not fk_columns:
                continue
            for pk, versions in table["rows"].items():
                version = self._visible(versions, None, self._horizon)
                if version is None:
                    continue
                for column in fk_columns:
                    value = version["values"].get(column["name"])
                    if value is None:
                        continue
                    parent = self.tables[column["references"]["table"]]
                    parent_versions = parent["rows"].get(value)
                    found = self._visible(parent_versions, None, self._horizon) if parent_versions else None
                    if found is None:
                        raise StorageError(
                            "table %s row %r has a dangling reference: no row %r in table %s"
                            % (name, pk, value, column["references"]["table"])
                        )

    def _write_chunks(self, txid, first_page, blob):
        size = self.pager.payload_size
        count = max(1, -(-len(blob) // size))
        for index in range(count):
            self.pager.write_page(txid, first_page + index, blob[index * size:(index + 1) * size])
        return count

    def _snapshot(self):
        tables = {}
        for name, table in self.tables.items():
            rows = []
            for pk in sorted(table["rows"], key=query.sort_key):
                version = self._visible(table["rows"][pk], None, self._horizon)
                if version is not None:
                    rows.append([pk, version["values"]])
            tables[name] = {
                "columns": table["columns"],
                "primary_key": table["primary_key"],
                "indexes": sorted(table["indexes"]),
                "rows": rows,
            }
        return {"format": DB_FORMAT, "tables": tables}

    def _committed_entries(self, table, column):
        """Sorted ``(value, pk)`` index entries of the committed row state."""
        entries = []
        for pk, versions in table["rows"].items():
            version = self._visible(versions, None, self._horizon)
            if version is None:
                continue
            value = version["values"].get(column)
            if value is not None:
                entries.append((value, pk))
        entries.sort(key=btree.entry_key)
        return entries

    def _check_index_pages(self, refs):
        """Validate the state blob's index page references against the rows.

        Every referenced B+ tree is walked and checked structurally (page ids,
        checksums via the pager, root to leaf connectivity, key order) and its
        entries must reproduce exactly the committed index entries of its
        column; every catalog index must be referenced exactly once.  Any
        mismatch means the image cannot be trusted, so it raises
        :class:`StorageError`.
        """
        if not isinstance(refs, list):
            raise StorageError("state record holds malformed index references")
        seen = set()
        for ref in refs:
            if (
                not isinstance(ref, dict)
                or not {"table", "column", "root"} <= set(ref)
                or not isinstance(ref["table"], str)
                or not isinstance(ref["column"], str)
            ):
                raise StorageError("state record holds a malformed index reference")
            name, column = ref["table"], ref["column"]
            if (name, column) in seen:
                raise StorageError("duplicate index pages for %s.%s" % (name, column))
            seen.add((name, column))
            table = self.tables.get(name)
            if table is None or column not in table["indexes"]:
                raise StorageError("index pages reference unknown index %s.%s" % (name, column))
            entries = btree.read_entries(
                self.pager.read_page, ref["root"], name, column, self.pager.page_count()
            )
            count = ref.get("entries")
            if count is not None and (
                not isinstance(count, int) or isinstance(count, bool) or count != len(entries)
            ):
                raise StorageError(
                    "index pages for %s.%s hold %d entries, state record says %r"
                    % (name, column, len(entries), count)
                )
            want = [list(e) for e in self._committed_entries(table, column)]
            if [list(e) for e in entries] != want:
                raise StorageError(
                    "index pages for %s.%s do not match the committed rows" % (name, column)
                )
        for name, table in self.tables.items():
            for column in table["indexes"]:
                if (name, column) not in seen:
                    raise StorageError(
                        "index %s.%s has no pages in the state record" % (name, column)
                    )

    def _index_layout(self, first_page):
        """Serialize every index's committed entries into B+ tree pages.

        Returns ``(refs, layout)``: the index references recorded in the
        state blob and a list of ``(first_page, payloads)`` page extents.
        """
        refs = []
        layout = []
        for name in sorted(self.tables):
            table = self.tables[name]
            for column in sorted(table["indexes"]):
                entries = self._committed_entries(table, column)
                payloads, root, height = btree.build_pages(
                    name, column, entries, first_page, self.pager.payload_size
                )
                refs.append({
                    "table": name,
                    "column": column,
                    "root": root,
                    "entries": len(entries),
                    "height": height,
                })
                layout.append((first_page, payloads))
                first_page += len(payloads)
        return refs, layout

    def _persist(self, tx):
        """Write audit, state and index pages plus the meta page, then commit.

        The index references live in the state blob (which spans as many
        pages as it needs), so the single meta page keeps its baseline shape
        and size no matter how many indexes exist.  The references name root
        page ids, which depend on the state blob's own length, so the layout
        is iterated to a fixed point before anything is written.
        """
        audit_lsn = self.pager.peek_lsn()
        entry = {"lsn": audit_lsn, "txid": tx.txid, "at": self._now(), "ops": list(tx.ops)}
        audit = self._audit + [entry]
        audit_blob = json.dumps(audit, sort_keys=True, separators=(",", ":")).encode("utf-8")
        audit_pages = self._write_chunks(tx.txid, AUDIT_PAGE, audit_blob)
        state_first = AUDIT_PAGE + audit_pages
        state = self._snapshot()
        refs = []
        layout = []
        for _ in range(8):
            state["index_refs"] = refs
            state_blob = json.dumps(state, sort_keys=True, separators=(",", ":")).encode("utf-8")
            state_pages = max(1, -(-len(state_blob) // self.pager.payload_size))
            new_refs, layout = self._index_layout(state_first + state_pages)
            if new_refs == refs:
                break
            refs = new_refs
        else:
            raise StorageError("index page layout did not converge")
        state_pages = self._write_chunks(tx.txid, state_first, state_blob)
        for first, payloads in layout:
            for offset, payload in enumerate(payloads):
                self.pager.write_page(tx.txid, first + offset, payload)
        meta_lsn = self.pager.peek_lsn()
        meta = {
            "format": STATE_FORMAT,
            "lsn": meta_lsn + 1,
            "txid": tx.txid,
            "audit_page": AUDIT_PAGE,
            "audit_pages": audit_pages,
            "audit_len": len(audit_blob),
            "state_page": state_first,
            "state_pages": state_pages,
            "state_len": len(state_blob),
            "next_txid": self._next_txid,
            "horizon": self._horizon,
        }
        self.pager.write_page(tx.txid, META_PAGE, json.dumps(meta, sort_keys=True).encode("utf-8"))
        lsn = self.pager.commit(tx.txid)
        self._audit = audit
        self.lsn = lsn
        return lsn

    # ------------------------------------------------------------- definition
    def _check_definition(self, name, columns, primary_key, indexes):
        if not isinstance(name, str) or not name.strip():
            raise StorageError("table name must be a non-empty string")
        if not isinstance(columns, list) or not columns:
            raise StorageError("table %s needs at least one column" % name)
        seen = set()
        for column in columns:
            if not isinstance(column, dict):
                raise StorageError("column definitions must be objects")
            cname = column.get("name")
            if not isinstance(cname, str) or not cname.strip():
                raise StorageError("column name must be a non-empty string")
            if cname in seen:
                raise StorageError("duplicate column %s" % cname)
            seen.add(cname)
            if column.get("type") not in TYPES:
                raise StorageError("column %s has unsupported type %r" % (cname, column.get("type")))
            for flag in ("nullable", "unique"):
                if flag in column and not isinstance(column[flag], bool):
                    raise StorageError("column %s: %s must be a boolean" % (cname, flag))
            if "references" in column:
                self._check_reference(name, column, column["references"])
        if primary_key not in seen:
            raise StorageError("primary key %r is not a column of table %s" % (primary_key, name))
        if indexes is None:
            indexes = []
        if not isinstance(indexes, (list, tuple)):
            raise StorageError("indexes must be a list of column names")
        for column in indexes:
            if column not in seen:
                raise StorageError("index column %r is not a column of table %s" % (column, name))

    def _check_reference(self, table, column, ref):
        """Validate one ``references`` object against the existing catalog."""
        cname = column["name"]
        if not isinstance(ref, dict) or set(ref) != {"table", "column"}:
            raise StorageError(
                "column %s of table %s: references must be an object "
                "with exactly 'table' and 'column'" % (cname, table)
            )
        target_name = ref["table"]
        target_column = ref["column"]
        if not isinstance(target_name, str) or not target_name.strip():
            raise StorageError("column %s of table %s: references.table must be a non-empty string" % (cname, table))
        if not isinstance(target_column, str) or not target_column.strip():
            raise StorageError("column %s of table %s: references.column must be a non-empty string" % (cname, table))
        target = self.tables.get(target_name)
        if target is None:
            raise StorageError(
                "column %s of table %s references unknown table %s" % (cname, table, target_name)
            )
        if target_column != target["primary_key"]:
            raise StorageError(
                "column %s of table %s references %s.%s, which is not the primary key"
                % (cname, table, target_name, target_column)
            )
        pk_column = [c for c in target["columns"] if c["name"] == target["primary_key"]][0]
        if pk_column["type"] != column["type"]:
            raise StorageError(
                "column %s of table %s has type %s but references %s.%s of type %s"
                % (cname, table, column["type"], target_name, target_column, pk_column["type"])
            )

    def create_table(self, name, columns, primary_key, indexes=None):
        with self._lock:
            self._check_definition(name, columns, primary_key, indexes)
            if name in self.tables:
                raise StorageError("table %s already exists" % name)
            tx = self._begin()
            try:
                catalog = []
                for column in columns:
                    entry = {
                        "name": column["name"],
                        "type": column["type"],
                        "nullable": False if column["name"] == primary_key else bool(column.get("nullable", True)),
                        "unique": True if column["name"] == primary_key else bool(column.get("unique", False)),
                    }
                    if column.get("references") is not None:
                        entry["references"] = {
                            "table": column["references"]["table"],
                            "column": column["references"]["column"],
                        }
                    catalog.append(entry)
                self.tables[name] = {
                    "name": name,
                    "columns": catalog,
                    "primary_key": primary_key,
                    "indexes": {},
                    "rows": {},
                }
                tx._undo.append(lambda: self._drop_table(name))
                for column in (indexes or []):
                    self._create_index(tx, name, column)
                tx.ops.append({
                    "op": "create_table",
                    "table": name,
                    "primary_key": primary_key,
                    "indexes": sorted(indexes or []),
                })
                tx.commit()
            except Exception:
                tx.rollback()
                raise
            return self.table_info(name)

    def _drop_table(self, name):
        self.tables.pop(name, None)
        for key in [k for k in self._indexes if k[0] == name]:
            self._indexes.pop(key, None)

    def create_index(self, table, column):
        with self._lock:
            tx = self._begin()
            try:
                name = self._create_index(tx, table, column)
                tx.ops.append({"op": "create_index", "table": table, "column": column})
                tx.commit()
            except Exception:
                tx.rollback()
                raise
            return name

    def _create_index(self, tx, table, column):
        table_obj = self._table(table)
        if column not in {col["name"] for col in table_obj["columns"]}:
            raise StorageError("unknown column %s.%s" % (table, column))
        if column in table_obj["indexes"]:
            raise StorageError("index on %s.%s already exists" % (table, column))
        table_obj["indexes"][column] = "%s_%s_idx" % (table, column)
        self._indexes[(table, column)] = btree.BPlusTree()
        self._rebuild_indexes(table_obj)
        tx._undo.append(lambda: self._drop_index(table, column))
        return table_obj["indexes"][column]

    def _drop_index(self, table, column):
        self._indexes.pop((table, column), None)
        table_obj = self.tables.get(table)
        if table_obj is not None:
            table_obj["indexes"].pop(column, None)

    def _rebuild_indexes(self, table):
        for column in table["indexes"]:
            tree = self._indexes.setdefault((table["name"], column), btree.BPlusTree())
            tree.bulk_load(self._committed_entries(table, column))

    def _index_add(self, table, values):
        """Add index entries for one row version; never duplicates.

        Entries of superseded versions are kept until nothing can read them
        any more (see ``_finish``), so an index scan stays correct for readers
        that still hold an older snapshot.
        """
        table_obj = self.tables[table]
        pk = values[table_obj["primary_key"]]
        for column in table_obj["indexes"]:
            value = values.get(column)
            if value is None:
                continue
            tree = self._indexes.setdefault((table, column), btree.BPlusTree())
            tree.insert((value, pk))

    # ------------------------------------------------------------- row writes
    def _build_values(self, table, row, current):
        if not isinstance(row, dict):
            raise ConstraintError("row must be a JSON object")
        columns = {col["name"]: col for col in table["columns"]}
        unknown = sorted(key for key in row if key not in columns)
        if unknown:
            raise StorageError("unknown column(s) %s on table %s" % (", ".join(unknown), table["name"]))
        merged = dict(current or {})
        merged.update(row)
        values = {}
        for column in table["columns"]:
            name = column["name"]
            value = merged.get(name)
            if value is None:
                if not column["nullable"]:
                    raise ConstraintError("column %s of %s may not be null" % (name, table["name"]))
                values[name] = None
            elif not query.check_type(value, column["type"]):
                raise ConstraintError(
                    "column %s of %s expects %s" % (name, table["name"], column["type"])
                )
            else:
                values[name] = value
        return values

    def _check_unique(self, tx, table, values, exclude_pk):
        primary_key = table["primary_key"]
        for column in table["columns"]:
            name = column["name"]
            if name == primary_key or not column["unique"]:
                continue
            value = values[name]
            if value is None:
                continue
            for pk, versions in table["rows"].items():
                if pk == exclude_pk:
                    continue
                version = self._visible(versions, tx.txid, tx.snapshot)
                if version is not None and version["values"].get(name) == value:
                    raise ConstraintError("unique constraint violated on %s.%s" % (table["name"], name))
                seen = self._conflicting_writes(versions, tx)
                if seen is not None and seen["values"].get(name) == value and seen["deleted"] is None:
                    raise ConflictError(
                        "concurrent write on unique column %s.%s" % (table["name"], name)
                    )

    # ---------------------------------------------------------- foreign keys
    def _fk_visible(self, versions, txid, horizon):
        """Visibility for foreign key checks.

        Unlike :meth:`_visible` (which keeps a version readable to the
        transaction that deleted it, so an update chain stays readable), a
        row this transaction deleted no longer counts here: it will not be
        part of the committed state, so it can neither satisfy a child
        reference nor keep a parent alive.
        """
        best = None
        for version in versions:
            created = version["created"]
            deleted = version["deleted"]
            if created != txid and not (self._is_committed(created) and created <= horizon):
                continue
            if deleted is None:
                best = version
            elif deleted != txid and not (self._is_committed(deleted) and deleted <= horizon):
                best = version
        return best

    def _referrers(self, table_name):
        """``(child_table, column)`` pairs whose foreign key targets ``table_name``."""
        found = []
        for child_name, child in self.tables.items():
            for column in child["columns"]:
                ref = column.get("references")
                if ref is not None and ref["table"] == table_name:
                    found.append((child_name, column["name"]))
        return found

    def _check_fk_values(self, tx, table, values):
        """Every non-null foreign key value must resolve in this transaction's view."""
        for column in table["columns"]:
            ref = column.get("references")
            if ref is None:
                continue
            value = values.get(column["name"])
            if value is None:
                continue
            parent = self.tables[ref["table"]]
            versions = parent["rows"].get(value)
            version = self._fk_visible(versions, tx.txid, tx.snapshot) if versions else None
            if version is None:
                raise ConstraintError(
                    "foreign key violation on %s.%s: no row %r in table %s"
                    % (table["name"], column["name"], value, ref["table"])
                )

    def _check_fk_delete(self, tx, table_name, pk):
        """A parent row cannot be deleted while a visible child references it."""
        for child_name, column_name in self._referrers(table_name):
            child = self.tables[child_name]
            for versions in child["rows"].values():
                version = self._fk_visible(versions, tx.txid, tx.snapshot)
                if version is not None and version["values"].get(column_name) == pk:
                    raise ConstraintError(
                        "foreign key violation: row %r of table %s is still "
                        "referenced by %s.%s" % (pk, table_name, child_name, column_name)
                    )

    def _record_fk_refs(self, tx, table, values):
        for column in table["columns"]:
            ref = column.get("references")
            if ref is not None:
                value = values.get(column["name"])
                if value is not None:
                    tx._fk_refs.append((ref["table"], value))

    def _check_foreign_keys(self, tx):
        """Re-validate a committing transaction's foreign key effects.

        A concurrent transaction may have committed after the per-operation
        checks ran — deleting a parent this transaction referenced, or
        inserting a child that references a parent it deleted.  Replaying the
        checks against the newest committed state (plus this transaction's
        own writes) keeps a commit from leaving a dangling reference behind.
        """
        for parent_name, pk in tx._fk_refs:
            parent = self.tables.get(parent_name)
            versions = parent["rows"].get(pk) if parent is not None else None
            version = self._fk_visible(versions, tx.txid, self._horizon) if versions else None
            if version is None:
                raise ConstraintError(
                    "foreign key violation: no row %r in table %s at commit" % (pk, parent_name)
                )
        for parent_name, pk in tx._fk_dels:
            for child_name, column_name in self._referrers(parent_name):
                child = self.tables[child_name]
                for versions in child["rows"].values():
                    version = self._fk_visible(versions, tx.txid, self._horizon)
                    if version is not None and version["values"].get(column_name) == pk:
                        raise ConstraintError(
                            "foreign key violation: row %r of table %s is still "
                            "referenced by %s.%s" % (pk, parent_name, child_name, column_name)
                        )

    def _insert(self, tx, table, row):
        table_obj = self._table(table)
        values = self._build_values(table_obj, row, None)
        pk = values[table_obj["primary_key"]]
        versions = table_obj["rows"].get(pk, [])
        if self._visible(versions, tx.txid, tx.snapshot) is not None:
            raise ConstraintError("duplicate primary key %r in table %s" % (pk, table))
        if self._conflicting_writes(versions, tx) is not None:
            raise ConflictError("primary key %r in table %s is written by another transaction" % (pk, table))
        self._check_unique(tx, table_obj, values, None)
        self._check_fk_values(tx, table_obj, values)
        version = {"created": tx.txid, "deleted": None, "values": values}
        table_obj["rows"].setdefault(pk, []).append(version)
        self._index_add(table, values)

        def undo():
            chain = table_obj["rows"].get(pk)
            if chain and version in chain:
                chain.remove(version)
            if chain is not None and not chain:
                table_obj["rows"].pop(pk, None)

        tx._undo.append(undo)
        self._record_fk_refs(tx, table_obj, values)
        tx.ops.append({"op": "insert", "table": table, "pk": pk, "row": values})
        return dict(values)

    def _update(self, tx, table, pk, patch):
        table_obj = self._table(table)
        pk = self._coerce_pk(table_obj, pk)
        if not isinstance(patch, dict) or not patch:
            raise StorageError("update needs a non-empty patch object")
        versions = table_obj["rows"].get(pk)
        version = self._visible(versions, tx.txid, tx.snapshot) if versions else None
        if version is None:
            if versions and self._conflicting_writes(versions, tx) is not None:
                raise ConflictError("row %r of %s was written after transaction %d started" % (pk, table, tx.txid))
            raise StorageError("row %r not found in table %s" % (pk, table))
        if self._conflicting_writes(versions, tx) is not None:
            raise ConflictError("row %r of %s was written after transaction %d started" % (pk, table, tx.txid))
        values = self._build_values(table_obj, patch, version["values"])
        if values[table_obj["primary_key"]] != pk:
            raise ConstraintError("primary key of %s may not be updated" % table)
        self._check_unique(tx, table_obj, values, pk)
        self._check_fk_values(tx, table_obj, values)
        version["deleted"] = tx.txid
        new_version = {"created": tx.txid, "deleted": None, "values": values}
        versions.append(new_version)
        self._index_add(table, values)

        def undo():
            version["deleted"] = None
            if new_version in versions:
                versions.remove(new_version)

        tx._undo.append(undo)
        self._record_fk_refs(tx, table_obj, values)
        tx.ops.append({"op": "update", "table": table, "pk": pk, "patch": dict(patch)})
        return dict(values)

    def _delete(self, tx, table, pk):
        table_obj = self._table(table)
        pk = self._coerce_pk(table_obj, pk)
        versions = table_obj["rows"].get(pk)
        version = self._visible(versions, tx.txid, tx.snapshot) if versions else None
        if version is None:
            if versions and self._conflicting_writes(versions, tx) is not None:
                raise ConflictError("row %r of %s was written after transaction %d started" % (pk, table, tx.txid))
            raise StorageError("row %r not found in table %s" % (pk, table))
        if self._conflicting_writes(versions, tx) is not None:
            raise ConflictError("row %r of %s was written after transaction %d started" % (pk, table, tx.txid))
        self._check_fk_delete(tx, table, pk)
        version["deleted"] = tx.txid

        def undo():
            version["deleted"] = None

        tx._undo.append(undo)
        tx._fk_dels.append((table, pk))
        tx.ops.append({"op": "delete", "table": table, "pk": pk})
        return dict(version["values"])

    # ------------------------------------------------------------ transactions
    def _resolve_isolation(self, isolation, snapshot):
        """Validate the ``isolation``/``snapshot`` combination before any begin."""
        if isolation is None:
            isolation = "snapshot"
        if not isinstance(isolation, str) or isolation not in ("snapshot", "serializable"):
            raise StorageError("isolation must be 'snapshot' or 'serializable'")
        if isolation == "serializable" and snapshot is not None:
            raise StorageError("a serializable transaction cannot be pinned to a snapshot")
        return isolation

    def _begin(self, snapshot=None, isolation=None):
        isolation = self._resolve_isolation(isolation, snapshot)
        if snapshot is not None:
            snapshot = int(snapshot)
            if snapshot < 0 or snapshot > self._horizon:
                raise StorageError("snapshot %d is outside the committed range 0..%d" % (snapshot, self._horizon))
        else:
            snapshot = self._horizon
        txid = self._next_txid
        self._next_txid += 1
        self._open.add(txid)
        return Transaction(self, txid, snapshot, isolation)

    def begin(self, snapshot=None, isolation=None):
        """Start a write transaction, optionally pinned to an older snapshot.

        ``isolation`` is ``"snapshot"`` (the default) or ``"serializable"``;
        the serializable mode validates reads at commit time and cannot be
        combined with a pinned ``snapshot``.
        """
        with self._lock:
            return self._begin(snapshot, isolation)

    def _finish(self, tx, committed):
        """Retire a transaction; the last one out rebuilds the indexes."""
        self._open.discard(tx.txid)
        if committed:
            self._committed.add(tx.txid)
            self._commit_counter += 1
            self._commit_seq[tx.txid] = self._commit_counter
            if tx.txid > self._horizon:
                self._horizon = tx.txid
        if not self._open:
            for name in list(self.tables):
                self._rebuild_indexes(self.tables[name])

    def insert(self, table, row):
        with self._lock:
            tx = self._begin()
            try:
                values = self._insert(tx, table, row)
                tx.commit()
                return values
            except Exception:
                if tx.state == "active":
                    tx.rollback()
                raise

    def update(self, table, pk, patch):
        with self._lock:
            tx = self._begin()
            try:
                values = self._update(tx, table, pk, patch)
                tx.commit()
                return values
            except Exception:
                if tx.state == "active":
                    tx.rollback()
                raise

    def delete(self, table, pk):
        with self._lock:
            tx = self._begin()
            try:
                values = self._delete(tx, table, pk)
                tx.commit()
                return values
            except Exception:
                if tx.state == "active":
                    tx.rollback()
                raise

    def transaction(self, ops, snapshot=None, isolation=None):
        """Apply a batch of operations in one transaction; roll back on error."""
        with self._lock:
            tx = self._begin(snapshot, isolation)
            try:
                for op in ops:
                    if not isinstance(op, dict):
                        raise StorageError("each op must be a JSON object")
                    kind = op.get("op")
                    if kind == "insert":
                        tx.insert(op["table"], op.get("row") or {})
                    elif kind == "update":
                        tx.update(op["table"], op.get("pk"), op.get("patch") or {})
                    elif kind == "delete":
                        tx.delete(op["table"], op.get("pk"))
                    elif kind == "savepoint":
                        tx.savepoint(op.get("name"))
                    elif kind == "rollback_to":
                        tx.rollback_to(op.get("name"))
                    elif kind == "release_savepoint":
                        tx.release_savepoint(op.get("name"))
                    else:
                        raise StorageError("unsupported op %r" % (kind,))
                lsn = tx.commit()
                return {"committed": True, "lsn": lsn, "txid": tx.txid}
            except Exception:
                if tx.state == "active":
                    tx.rollback()
                raise

    # ------------------------------------------------------------ read helpers
    def get(self, table, pk):
        with self._lock:
            return self._get(self._reader(), table, pk)

    def scan(self, table):
        with self._lock:
            return self._scan(self._reader(), table)

    def index_get(self, table, column, value):
        with self._lock:
            return self._index_lookup(self._reader(), table, column, value, value)

    def index_range(self, table, column, low=None, high=None):
        with self._lock:
            return self._index_lookup(self._reader(), table, column, low, high)

    def query(self, table, columns=None, where=None, index_hint=None, limit=None, order_by=None):
        with self._lock:
            return query.execute(
                self, table, columns=columns, where=where, index_hint=index_hint,
                limit=limit, order_by=order_by,
            )

    def explain(self, table, where=None, index_hint=None, **kwargs):
        with self._lock:
            return query.explain(self, table, where=where, index_hint=index_hint, **kwargs)

    def audit(self, limit=None):
        with self._lock:
            entries = [dict(entry) for entry in self._audit]
        if limit is None:
            return entries
        limit = int(limit)
        if limit < 0:
            raise StorageError("limit must be greater than or equal to 0")
        return entries[len(entries) - limit:] if limit else []

    def readonly_view(self):
        return ReadOnlyView(self)

    def create_replica(self, replica_dir):
        """Build an initial persistent read-only replica in ``replica_dir``."""
        from .replica import Replica

        return Replica.create(self, replica_dir)

    # -------------------------------------------------- recovery and integrity
    def reopen(self):
        """Simulate a restart: drop memory, replay the WAL, reload the state."""
        with self._lock:
            self.pager = Pager(self.root, self.page_size)
            self._reset()
            self._load()
            return {"tables": sorted(self.tables), "lsn": self.lsn, "pages": self.pager.page_count()}

    def verify(self):
        with self._lock:
            pages = self.pager.page_count()
            crc_ok = True
            for page_id in range(pages):
                try:
                    self.pager.read_page(page_id)
                except StorageError:
                    crc_ok = False
            return {
                "pages": pages,
                "wal_records": self.pager.wal_records(),
                "crc_ok": crc_ok,
                "ok": bool(crc_ok and self._indexes_consistent() and self._index_pages_ok()),
            }

    def _index_pages_ok(self):
        """True when the persisted B+ tree pages match the committed state.

        Images written before paged indexes existed carry no index references
        and pass trivially; anything unreadable, unconnected, unsorted or
        disagreeing with the committed rows fails the check.
        """
        if self.pager.page_count() == 0:
            return True
        try:
            meta = self._read_json(META_PAGE)
            if not isinstance(meta, dict) or meta.get("format") != STATE_FORMAT:
                return False
            blob = self._read_pages(meta["state_page"], meta["state_pages"], meta["state_len"])
            state = json.loads(blob.decode("utf-8"))
            if not isinstance(state, dict):
                return False
            refs = state.get("index_refs")
            if refs is None:
                return True
            self._check_index_pages(refs)
            return True
        except (StorageError, ValueError):
            return False

    def _indexes_consistent(self):
        for (table, column), tree in self._indexes.items():
            table_obj = self.tables.get(table)
            if table_obj is None:
                return False
            for value, pk in tree:
                versions = table_obj["rows"].get(pk)
                if not versions or not any(v["values"].get(column) == value for v in versions):
                    return False
            for pk, versions in table_obj["rows"].items():
                version = self._visible(versions, None, self._horizon)
                if version is None:
                    continue
                value = version["values"].get(column)
                if value is not None and (value, pk) not in tree:
                    return False
        return True

    # ------------------------------------------------------------------ backup
    def backup(self, path):
        """Write a consistent copy: pages + WAL + manifest with the current lsn."""
        with self._lock:
            path = os.path.abspath(path)
            os.makedirs(path, exist_ok=True)
            manifest = {
                "format": BACKUP_FORMAT,
                "lsn": self.lsn,
                "at": self._now(),
                "tables": sorted(self.tables),
                "pages": self.pager.page_count(),
                "wal_records": self.pager.wal_records(),
                "page_size": self.page_size,
            }
            shutil.copyfile(self.pager.data_path, os.path.join(path, "data.pages"))
            shutil.copyfile(self.pager.wal_path, os.path.join(path, "wal.log"))
            with open(os.path.join(path, "manifest.json"), "w", encoding="utf-8") as fh:
                fh.write(json.dumps(manifest, sort_keys=True, separators=(",", ":")) + "\n")
            manifest["path"] = path
            return manifest

    def restore(self, path, to_lsn=None):
        """Restore a backup, optionally to the committed state at ``to_lsn``."""
        with self._lock:
            path = os.path.abspath(path)
            manifest_path = os.path.join(path, "manifest.json")
            if not os.path.exists(manifest_path):
                raise StorageError("backup manifest not found in %s" % path)
            with open(manifest_path, "r", encoding="utf-8") as fh:
                manifest = json.load(fh)
            if manifest.get("format") != BACKUP_FORMAT:
                raise StorageError("unknown backup format %r" % manifest.get("format"))
            target = int(manifest["lsn"]) if to_lsn is None else int(to_lsn)
            if target > int(manifest["lsn"]):
                raise StorageError("lsn %d is newer than backup lsn %d" % (target, manifest["lsn"]))
            records, _ = read_wal(os.path.join(path, "wal.log"))
            markers = commit_lsns(records)
            if target != int(manifest["lsn"]) and (not markers or target < markers[0]):
                raise StorageError("no committed state at or before lsn %d in this backup" % target)
            self._validate_restore(path, records, markers, target)
            shutil.copyfile(os.path.join(path, "data.pages"), self.pager.data_path)
            shutil.copyfile(os.path.join(path, "wal.log"), self.pager.wal_path)
            self.pager = Pager(self.root, self.page_size, auto_replay=False)
            applied = self.pager.replay(max_lsn=target)
            self._reset()
            self._load()
            return {
                "requested_lsn": target,
                "restored_lsn": self.lsn,
                "applied_records": applied,
                "tables": sorted(self.tables),
            }

    def _validate_restore(self, path, records, markers, target):
        """Replay the restore target in a scratch directory and load it there.

        The load runs the foreign key validation (and every other state
        check), so a backup that would not open raises before the live
        directory and the in-memory state are touched.
        """
        from .replica import _wal_prefix

        reachable = [lsn for lsn in markers if lsn <= target]
        wal_blob = _wal_prefix(records, max(reachable)) if reachable else b""
        staging = tempfile.mkdtemp(prefix="kvse-restore-")
        try:
            shutil.copyfile(os.path.join(path, "data.pages"), os.path.join(staging, "data.pages"))
            with open(os.path.join(staging, "wal.log"), "wb") as fh:
                fh.write(wal_blob)
            Engine(staging, page_size=self.page_size)
        finally:
            shutil.rmtree(staging, ignore_errors=True)


class Transaction:
    """A snapshot or serializable transaction; read-only until it writes."""

    def __init__(self, engine, txid, snapshot, isolation="snapshot"):
        self.engine = engine
        self.txid = txid
        self.snapshot = snapshot
        self.isolation = isolation
        self.state = "active"
        self.ops = []
        self._undo = []
        self._reads = []
        self._fk_refs = []
        self._fk_dels = []
        self._savepoints = []
        self._suppress = 0
        self._commit_horizon = engine._commit_counter

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc, tb):
        if self.state == "active":
            self.rollback() if exc_type else self.commit()
        return False

    def _check_active(self):
        if self.state != "active":
            raise StorageError("transaction %d is %s" % (self.txid, self.state))

    # ------------------------------------------------------------------ writes
    def insert(self, table, row):
        self._check_active()
        with self.engine._lock:
            return self.engine._insert(self, table, row)

    def update(self, table, pk, patch):
        self._check_active()
        with self.engine._lock:
            return self.engine._update(self, table, pk, patch)

    def delete(self, table, pk):
        self._check_active()
        with self.engine._lock:
            return self.engine._delete(self, table, pk)

    # ------------------------------------------------------------------- reads
    def get(self, table, pk):
        self._check_active()
        with self.engine._lock:
            return self.engine._get(self, table, pk)

    def scan(self, table):
        self._check_active()
        with self.engine._lock:
            return self.engine._scan(self, table)

    def index_get(self, table, column, value):
        self._check_active()
        with self.engine._lock:
            return self.engine._index_lookup(self, table, column, value, value)

    def index_range(self, table, column, low=None, high=None):
        self._check_active()
        with self.engine._lock:
            return self.engine._index_lookup(self, table, column, low, high)

    def table_info(self, name):
        return self.engine.table_info(name)

    def query(self, table, columns=None, where=None, index_hint=None, limit=None, order_by=None):
        self._check_active()
        with self.engine._lock:
            if self.isolation != "serializable":
                return query.execute(
                    self, table, columns=columns, where=where, index_hint=index_hint,
                    limit=limit, order_by=order_by,
                )
            # A serializable query protects the full matching range of every
            # where predicate; the access path, projection, ordering and limit
            # must not narrow it, so the reads done by the executor itself are
            # suppressed and the whole predicate is recorded once it succeeds.
            conds = query.normalize_where(self, table, where)
            self._suppress += 1
            try:
                result = query.execute(
                    self, table, columns=columns, where=where, index_hint=index_hint,
                    limit=limit, order_by=order_by,
                )
            finally:
                self._suppress -= 1
            self._reads.append(("where", table, tuple(conds)))
            return result

    # -------------------------------------------------------------- savepoints
    def savepoint(self, name):
        """Mark a named point this transaction can later roll back to.

        Names are case-sensitive and live only inside this transaction; a
        name freed by ``rollback_to`` or ``release_savepoint`` may be reused.
        """
        self._check_active()
        with self.engine._lock:
            _check_savepoint_name(name)
            if any(sp["name"] == name for sp in self._savepoints):
                raise StorageError(
                    "savepoint %r already exists in transaction %d" % (name, self.txid)
                )
            self._savepoints.append({
                "name": name,
                "undo": len(self._undo),
                "ops": len(self.ops),
                "fk_refs": len(self._fk_refs),
                "fk_dels": len(self._fk_dels),
            })
            return True

    def rollback_to(self, name):
        """Undo every write made after ``name`` was created; keep it and the
        earlier savepoints, invalidate the later ones.

        Read predicates already recorded by a serializable transaction stay
        protected even when the writes around them are undone.
        """
        self._check_active()
        with self.engine._lock:
            index = self._find_savepoint(name)
            target = self._savepoints[index]
            while len(self._undo) > target["undo"]:
                self._undo.pop()()
            del self.ops[target["ops"]:]
            del self._fk_refs[target["fk_refs"]:]
            del self._fk_dels[target["fk_dels"]:]
            del self._savepoints[index + 1:]
            return True

    def release_savepoint(self, name):
        """Forget ``name`` and every savepoint created after it.

        Nothing is undone and nothing is committed: the writes stay exactly
        as they are and a full ``rollback`` still undoes all of them.
        """
        self._check_active()
        with self.engine._lock:
            index = self._find_savepoint(name)
            del self._savepoints[index:]
            return True

    def _find_savepoint(self, name):
        _check_savepoint_name(name)
        for index, sp in enumerate(self._savepoints):
            if sp["name"] == name:
                return index
        raise StorageError("unknown savepoint %r in transaction %d" % (name, self.txid))

    # -------------------------------------------------------------- lifecycle
    def commit(self):
        with self.engine._lock:
            self._check_active()
            if self.txid == 0:
                raise StorageError("read-only snapshots cannot be committed")
            engine = self.engine
            if self.isolation == "serializable":
                try:
                    engine._check_read_conflicts(self)
                except ConflictError:
                    # A read-write conflict rolls the transaction back for
                    # good: undo row and index changes, write no audit record
                    # and leave the committed lsn untouched.
                    self._rollback_locked()
                    engine.pager.abort(self.txid)
                    self.state = "rolled_back"
                    engine._finish(self, False)
                    raise
            try:
                engine._check_foreign_keys(self)
            except ConstraintError:
                # A dangling reference at commit gets the same treatment as a
                # serializable conflict: the whole transaction is undone and
                # nothing reaches the WAL, the lsn or the audit log.
                self._rollback_locked()
                engine.pager.abort(self.txid)
                self.state = "rolled_back"
                engine._finish(self, False)
                raise
            engine._committed.add(self.txid)
            if self.txid > engine._horizon:
                engine._horizon = self.txid
            try:
                lsn = engine._persist(self)
            except Exception:
                engine._committed.discard(self.txid)
                self._rollback_locked()
                self.state = "failed"
                raise
            self.state = "committed"
            self._undo = []
            self._fk_refs = []
            self._fk_dels = []
            self._savepoints = []
            engine._finish(self, True)
            return lsn

    def rollback(self):
        with self.engine._lock:
            self._check_active()
            if self.txid != 0:
                self._rollback_locked()
                self.engine.pager.abort(self.txid)
            self.state = "rolled_back"
            self.engine._finish(self, False)
            return True

    def _rollback_locked(self):
        while self._undo:
            self._undo.pop()()
        self.ops = []
        self._fk_refs = []
        self._fk_dels = []
        self._savepoints = []


class ReadOnlyView:
    """Handle returned by :meth:`Engine.readonly_view`; every write is refused."""

    _ALLOWED = (
        "get", "scan", "query", "explain", "index_get", "index_range",
        "table_info", "list_tables", "has_table", "audit", "verify",
    )

    def __init__(self, engine):
        self._engine = engine

    def __getattr__(self, name):
        if name in ReadOnlyView._ALLOWED:
            return getattr(self._engine, name)
        raise StorageError("read-only view rejects %s" % name)

"""Standard library HTTP front end: JSON over HTTP/1.1.

Routes
------
GET  /healthz                      -> {"ok": true}
POST /v1/tables                    -> 201 catalog info
GET  /v1/tables                    -> 200 {"tables": [...]}
POST /v1/tables/{table}/rows       -> 201 {"inserted": n}
GET  /v1/tables/{table}/rows/{pk}  -> 200 row / 404
POST /v1/query                     -> 200 {"rows": [...], "access": "index"|"scan"}
POST /v1/tx                        -> 200 {"committed": true, "lsn": n} / 409
GET  /v1/verify                    -> 200 integrity report
GET  /v1/audit?limit=n             -> 200 {"entries": [...], "count": n}

Every failure is answered with a JSON body ``{"error": "..."}``.
"""

from __future__ import annotations

import json
import re
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import parse_qs, unquote, urlparse

from .engine import ConflictError, ConstraintError, Engine, StorageError

ROW_PATH = re.compile(r"^/v1/tables/([^/]+)/rows(?:/(.*))?$")


def coerce(text, type_name):
    """Convert a path/text value into the declared column type."""
    if type_name == "int":
        try:
            return int(text)
        except (TypeError, ValueError):
            raise StorageError("value %r is not an int" % (text,))
    if type_name == "bool":
        lowered = str(text).lower()
        if lowered in ("true", "1"):
            return True
        if lowered in ("false", "0"):
            return False
        raise StorageError("value %r is not a bool" % (text,))
    return text


class Handler(BaseHTTPRequestHandler):
    server_version = "kvse/0.1"
    protocol_version = "HTTP/1.1"

    def log_message(self, fmt, *args):  # keep CLI stdout clean
        return

    # ---------------------------------------------------------------- plumbing
    def _send(self, status, payload):
        body = json.dumps(payload, sort_keys=True).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def _error(self, status, message):
        self._send(status, {"error": message})

    def _status_for(self, exc):
        if isinstance(exc, (ConflictError, ConstraintError)):
            return 409
        return 400

    def _body(self):
        length = int(self.headers.get("Content-Length") or 0)
        if length <= 0:
            return {}
        raw = self.rfile.read(length)
        try:
            data = json.loads(raw.decode("utf-8"))
        except (UnicodeDecodeError, ValueError) as exc:
            raise StorageError("invalid JSON body: %s" % exc)
        if not isinstance(data, dict):
            raise StorageError("request body must be a JSON object")
        return data

    @property
    def engine(self):
        return self.server.engine

    # -------------------------------------------------------------------- GET
    def do_GET(self):
        try:
            parsed = urlparse(self.path)
            path = parsed.path.rstrip("/") or "/"
            if path == "/healthz":
                return self._send(200, {"ok": True})
            if path == "/v1/tables":
                return self._send(200, {"tables": self.engine.list_tables()})
            if path == "/v1/verify":
                return self._send(200, self.engine.verify())
            if path == "/v1/audit":
                limit = parse_qs(parsed.query).get("limit", [None])[0]
                limit = int(limit) if limit not in (None, "") else None
                entries = self.engine.audit(limit=limit)
                return self._send(200, {"entries": entries, "count": len(entries)})
            match = ROW_PATH.match(path)
            if match:
                return self._get_row(unquote(match.group(1)), unquote(match.group(2) or ""))
            return self._error(404, "no route for GET %s" % path)
        except Exception as exc:  # noqa: BLE001 - reported as a JSON error
            return self._error(self._status_for(exc), str(exc))

    def _get_row(self, table, pk_text):
        if not self.engine.has_table(table):
            return self._error(404, "unknown table %s" % table)
        info = self.engine.table_info(table)
        column = [c for c in info["columns"] if c["name"] == info["primary_key"]][0]
        row = self.engine.get(table, coerce(pk_text, column["type"]))
        if row is None:
            return self._error(404, "row %s not found in table %s" % (pk_text, table))
        return self._send(200, row)

    # ------------------------------------------------------------------- POST
    def do_POST(self):
        try:
            path = urlparse(self.path).path.rstrip("/") or "/"
            if path == "/v1/tables":
                return self._create_table(self._body())
            if path == "/v1/query":
                return self._query(self._body())
            if path == "/v1/tx":
                return self._tx(self._body())
            match = ROW_PATH.match(path)
            if match and not match.group(2):
                return self._insert_rows(unquote(match.group(1)), self._body())
            return self._error(404, "no route for POST %s" % path)
        except Exception as exc:  # noqa: BLE001 - reported as a JSON error
            return self._error(self._status_for(exc), str(exc))

    def _create_table(self, body):
        name = body.get("name")
        info = self.engine.create_table(
            name, body.get("columns") or [], body.get("primary_key"), body.get("indexes") or []
        )
        return self._send(201, dict(info, index_names=sorted(info["indexes"])))

    def _insert_rows(self, table, body):
        if not self.engine.has_table(table):
            return self._error(404, "unknown table %s" % table)
        rows = body.get("rows")
        if not isinstance(rows, list) or not rows:
            raise StorageError("body must contain a non-empty 'rows' array")
        tx = self.engine.begin()
        try:
            for row in rows:
                tx.insert(table, row)
            lsn = tx.commit()
        except Exception:
            tx.rollback()
            raise
        return self._send(201, {"inserted": len(rows), "table": table, "lsn": lsn})

    def _query(self, body):
        table = body.get("table")
        if not self.engine.has_table(table):
            return self._error(404, "unknown table %s" % table)
        result = self.engine.query(
            table,
            columns=body.get("columns"),
            where=body.get("where"),
            index_hint=body.get("index_hint"),
            limit=body.get("limit"),
            order_by=body.get("order_by"),
        )
        return self._send(200, result)

    def _tx(self, body):
        ops = body.get("ops")
        if not isinstance(ops, list) or not ops:
            raise StorageError("body must contain a non-empty 'ops' array")
        result = self.engine.transaction(
            ops, snapshot=body.get("snapshot_txid"), isolation=body.get("isolation")
        )
        return self._send(200, result)


class Server(ThreadingHTTPServer):
    daemon_threads = True
    allow_reuse_address = True

    def __init__(self, address, engine):
        self.engine = engine
        super().__init__(address, Handler)


def create_server(engine, host="127.0.0.1", port=8080):
    """Bind a threading HTTP server for ``engine`` and return it unstarted."""
    if not isinstance(engine, Engine):
        raise StorageError("create_server expects an Engine instance")
    return Server((host, int(port)), engine)

"""Tiny query subset: scan, point get and index range on one column.

The module also owns the two small helpers shared with the engine
(``check_type`` for column types and ``sort_key`` for deterministic row
ordering) so that no import cycle is needed.

Supported predicates are ``[(column, op, value)]`` with ``op`` taken from
``OPS``.  The access path is chosen by the first predicate: when it targets an
indexed column and the operator can be served by a range scan, the index is
used, otherwise the table is scanned.
"""

from __future__ import annotations

from .pager import StorageError

OPS = ("=", "!=", "<", "<=", ">", ">=")
INDEX_OPS = ("=", "<", "<=", ">", ">=")


def check_type(value, type_name):
    """True when ``value`` is a legal value for a column of ``type_name``."""
    if type_name == "int":
        return isinstance(value, int) and not isinstance(value, bool)
    if type_name == "bool":
        return isinstance(value, bool)
    if type_name == "text":
        return isinstance(value, str)
    return False


def sort_key(value):
    """Ordering key that keeps mixed int/str/bool values deterministic."""
    if isinstance(value, bool):
        return (0, int(value), "")
    if isinstance(value, (int, float)):
        return (1, value, "")
    return (2, 0, "" if value is None else str(value))


def compare(op, left, right):
    if op == "=":
        return left == right
    if op == "!=":
        return left != right
    if left is None or right is None:
        return False
    try:
        if op == "<":
            return left < right
        if op == "<=":
            return left <= right
        if op == ">":
            return left > right
        if op == ">=":
            return left >= right
    except TypeError:
        raise StorageError("cannot compare %r with %r" % (left, right))
    raise StorageError("unsupported operator %r" % (op,))


def normalize_where(source, table, where):
    """Validate ``where`` and return a list of ``(column, op, value)``."""
    info = source.table_info(table)
    columns = {col["name"]: col for col in info["columns"]}
    if where is None:
        return []
    if not isinstance(where, (list, tuple)):
        raise StorageError("where must be a list of [column, op, value]")
    conds = []
    for item in where:
        if isinstance(item, (list, tuple)) and len(item) == 3:
            column, op, value = item
        elif isinstance(item, dict):
            column = item.get("column", item.get("col"))
            op = item.get("op", "=")
            value = item.get("value")
        else:
            raise StorageError("each where predicate must be [column, op, value]")
        if op not in OPS:
            raise StorageError("unsupported operator %r" % (op,))
        if column not in columns:
            raise StorageError("unknown column %s.%s" % (table, column))
        if value is not None and not check_type(value, columns[column]["type"]):
            raise StorageError(
                "predicate on %s.%s expects %s" % (table, column, columns[column]["type"])
            )
        conds.append((column, op, value))
    return conds


def _choose(info, conds, index_hint):
    indexes = info["indexes"]
    if index_hint and index_hint != "scan":
        column = index_hint if index_hint in indexes else None
        if column is None:
            for name, index_name in indexes.items():
                if index_name == index_hint:
                    column = name
                    break
        if column is None:
            raise StorageError("no usable index named %s on table %s" % (index_hint, info["name"]))
        for cond in conds:
            if cond[0] == column and cond[1] in INDEX_OPS:
                return "index", indexes[column]
        return "scan", None
    if conds and conds[0][1] in INDEX_OPS and conds[0][0] in indexes:
        return "index", indexes[conds[0][0]]
    return "scan", None


def plan(source, table, columns=None, where=None, index_hint=None, limit=None, order_by=None):
    conds = normalize_where(source, table, where)
    info = source.table_info(table)
    access, index_name = _choose(info, conds, index_hint)
    return {
        "table": table,
        "access": access,
        "index": index_name,
        "columns": list(columns) if columns else None,
        "where": [list(c) for c in conds],
        "limit": limit,
        "order_by": order_by,
    }


def explain(source, table, where=None, index_hint=None, **kwargs):
    chosen = plan(source, table, where=where, index_hint=index_hint, **kwargs)
    return {"access": chosen["access"], "index": chosen["index"]}


def execute(source, table, columns=None, where=None, index_hint=None, limit=None, order_by=None):
    conds = normalize_where(source, table, where)
    info = source.table_info(table)
    access, index_name = _choose(info, conds, index_hint)
    if access == "index":
        column, op, value = conds[0]
        if op == "=":
            rows = source.index_get(table, column, value)
        elif op in ("<", "<="):
            rows = source.index_range(table, column, None, value)
        else:
            rows = source.index_range(table, column, value, None)
        key_column = order_by or column
    else:
        rows = source.scan(table)
        key_column = order_by or info["primary_key"]
    if conds:
        rows = [row for row in rows if all(compare(op, row.get(col), val) for col, op, val in conds)]
    if order_by and order_by not in {col["name"] for col in info["columns"]}:
        raise StorageError("unknown column %s.%s" % (table, order_by))
    rows = sorted(rows, key=lambda row: sort_key(row.get(key_column)))
    if limit is not None:
        limit = int(limit)
        if limit < 0:
            raise StorageError("limit must be greater than or equal to 0")
        rows = rows[:limit]
    if columns:
        known = {col["name"] for col in info["columns"]}
        unknown = sorted(col for col in columns if col not in known)
        if unknown:
            raise StorageError("unknown column(s) %s on table %s" % (", ".join(unknown), table))
        rows = [{col: row.get(col) for col in columns} for row in rows]
    return {"rows": rows, "access": access, "index": index_name, "table": table}


def select(source, table, columns=None, where=None, index_hint=None, limit=None, order_by=None):
    """Convenience wrapper returning just the projected rows."""
    return execute(
        source,
        table,
        columns=columns,
        where=where,
        index_hint=index_hint,
        limit=limit,
        order_by=order_by,
    )["rows"]

